    n++;
    const esc = s => '`' + s.replace(/\|/g, '\\|').replace(/`/g, '‵') + '`';
    rows.push(`| ${n} | ${esc(c.a)} | ${esc(c.b)} | ${esc(JSON.stringify(out))} | ${r.status} |`);
  }
}
writeFileSync('/tmp/p/table.md', '| # | --a (instance) | --b (schema) | stdout (JSON-quoted) | rc |\n|---|---|---|---|---|\n' + rows.join('\n') + '\n');
